const knowledgeSimilarPosts = `-- name: KnowledgeSimilarPosts :many
select p.thread_id, t.title, (1 - (c.embedding <=> $1::vector))::float8 as cosine
from content_chunks c
join knowledge_items k on k.chunk_id = c.id and k.source_type = 'POST' and k.course_id = $2
join forum_posts p on p.id = k.source_id and p.course_id = k.course_id
join forum_threads t on t.id = p.thread_id and t.course_id = p.course_id
where c.course_ids @> array[$2::uuid] and c.embedding is not null
  and p.verification_state in ('VERIFIED', 'CORRECTED') and p.hidden_at is null and p.deleted_at is null
  and t.hidden_at is null and t.deleted_at is null
order by c.embedding <=> $1::vector
limit 3
`

type KnowledgeSimilarPostsParams struct {
	Vec      pgvector.Vector
	CourseID uuid.UUID
}

type KnowledgeSimilarPostsRow struct {
	ThreadID uuid.UUID
	Title    string
	Cosine   float64
}

// ---- M4 câu tương tự đã xác nhận ---------------------------------------------------------------------------------------------------
func (q *Queries) KnowledgeSimilarPosts(ctx context.Context, arg KnowledgeSimilarPostsParams) ([]KnowledgeSimilarPostsRow, error) {
	rows, err := q.db.Query(ctx, knowledgeSimilarPosts, arg.Vec, arg.CourseID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []KnowledgeSimilarPostsRow{}
	for rows.Next() {
		var i KnowledgeSimilarPostsRow
		if err := rows.Scan(&i.ThreadID, &i.Title, &i.Cosine); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

